def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    nodeinfo = {
        "@context": "https://www.w3.org/ns/nodeinfo/2.0/",
        "version": "2.0",
        "software": {
            "name": "NodeInfo Generator",
            "version": "1.0"
        },
        "usage": {
            "public": True,
            "private": False
        },
        "protocols": [
            "http",
            "https"
        ],
        "host": url,
        "links": [
            {
                "rel": "self",
                "href": f"{url}/.well-known/nodeinfo"
            }
        ]
    }

    if document_path:
        nodeinfo["links"].append({
            "rel": "self",
            "href": f"{url}/{document_path}"
        })

    return json.dumps(nodeinfo, indent=4)

